{'code': "from qgis.core import QgsApplication
res = {}
reg = QgsApplication.processingRegistry()
for aid in ['native:hublines','native:distancetonearesthub','qgis:distancetonearesthublinetohub','qgis:distancetonearesthubpoints']:
    a = reg.algorithmById(aid)
    try:
        inst = a.createInstance() if a else None
        res[aid] = {'registered': a is not None, 'instantiated': inst is not None,
                    'flags': str(a.flags()) if a else None}
    except Exception as e:
        res[aid] = {'registered': a is not None, 'error': str(e)}
result = res"}

